using InventoryService.Data;using InventoryService.Entities;using Microsoft.EntityFrameworkCore;namespace InventoryService.Services;public class BusinessException(string m):Exception(m);public class NotFoundException(string m):Exception(m);public interface IInventory{Task<Product>Save(string n,int q,CancellationToken c);Task<List<Product>>All(int p,int s,CancellationToken c);Task<Product?>Get(Guid id,CancellationToken c);Task<Product?>Update(Guid id,string n,int q,CancellationToken c);Task<bool>Delete(Guid id,CancellationToken c);Task<int>Reduce(Guid id,int q,CancellationToken c);Task<int>Restore(Guid id,int q,CancellationToken c);}public class Inventory(InventoryDbContext db):IInventory{public async Task<Product>Save(string n,int q,CancellationToken c){var p=new Product{ProductName=n,StockQty=q,CreatedAt=DateTime.UtcNow};db.Products.Add(p);await db.SaveChangesAsync(c);return p;}public Task<List<Product>>All(int p,int s,CancellationToken c)=>db.Products.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.ProductName).Skip((p-1)*s).Take(s).ToListAsync(c);public Task<Product?>Get(Guid id,CancellationToken c)=>db.Products.AsNoTracking().FirstOrDefaultAsync(x=>x.ProductId==id&&x.IsActive,c);public async Task<Product?>Update(Guid id,string n,int q,CancellationToken c){var p=await db.Products.FirstOrDefaultAsync(x=>x.ProductId==id&&x.IsActive,c);if(p==null)return null;p.ProductName=n;p.StockQty=q;p.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync(c);return p;}public async Task<bool>Delete(Guid id,CancellationToken c){var p=await db.Products.FirstOrDefaultAsync(x=>x.ProductId==id&&x.IsActive,c);if(p==null)return false;p.IsActive=false;p.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync(c);return true;}public async Task<int>Reduce(Guid id,int q,CancellationToken c){var n=await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE products SET stock_qty=stock_qty-{q},updated_at=CURRENT_TIMESTAMP WHERE product_id={id} AND is_active=TRUE AND stock_qty>={q}",c);if(n!=1)throw new BusinessException("Insufficient stock or inactive product.");return (await Get(id,c))!.StockQty;}public async Task<int>Restore(Guid id,int q,CancellationToken c){var n=await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE products SET stock_qty=stock_qty+{q},updated_at=CURRENT_TIMESTAMP WHERE product_id={id} AND is_active=TRUE",c);if(n!=1)throw new NotFoundException("Product not found.");return (await Get(id,c))!.StockQty;}}